// StudyBara pet artwork update. Adds presentation only; does not change saved data or timer/planner logic.
const PET_ART = {"greeting": "data:image/png;base64,", "studious": "data:image/png;base64,", "sleeping": "data:image/png;base64,", "celebrating": "data:image/png;base64,", "break": "data:image/png;base64,", "classicAwake": "data:image/png;base64,", "classicRest": "data:image/png;base64,"}
const COPY = {
  greeting: ['Your capybara companion waving hello', 'Ready when you are.'],
  studious: ['Your capybara studying with a laptop', 'One small step at a time.'],
  sleeping: ['Your capybara asleep on a pillow', 'Rest is part of studying.'],
  break: ['Your capybara enjoying a warm drink', 'Take a moment. Resume when ready.'],
  celebrating: ['Your capybara celebrating a completed task', 'Nice work!']
}
const STYLE = `
.pet-companion {margin:20px 0 0;padding:12px;border-top:1px solid #e8dac4;}
.pet-companion .pet {margin:0;}
.pet-companion .pet-art {height:150px;max-width:220px;}
.pet-notice {position:fixed;z-index:1000;bottom:18px;right:18px;width:250px;max-width:calc(100vw - 36px);background:#fffaf0;color:#352b21;border:1px solid #d9ba8b;border-radius:18px;box-shadow:0 8px 28px #352b2130;padding:14px;text-align:center;}
.pet-notice[hidden] {display:none;}
.pet-notice img {display:block;width:100%;height:145px;object-fit:contain;}
.pet-notice p {margin:8px 0;overflow-wrap:anywhere;}
.pet-notice button {min-height:44px;font:inherit;padding:6px 14px;background:#68451f;color:#fff;border:0;border-radius:9px;cursor:pointer;}
.pet-notice button:focus-visible {outline:3px solid #315d47;outline-offset:3px;}
@media(max-width:650px){.pet-notice{width:210px;bottom:12px;right:12px}.pet-notice img{height:115px}}
`
function initPetUpgrade() {
  const root = document.querySelector('#app')
  if (!root || root.dataset.petUpgradeReady === '1') return
  root.dataset.petUpgradeReady = '1'
  const style = document.createElement('style'); style.id='studybara-pet-styles'; style.textContent=STYLE; document.head.appendChild(style)
  let noticeState=null, noticeTimer=null, scheduled=false, previousCompletion=''
  const notice=document.createElement('aside');notice.className='pet-notice';notice.id='petNotice';notice.hidden=true
  notice.setAttribute('aria-label','Study companion update')
  const noticeImage=document.createElement('img');noticeImage.alt=''
  const message=document.createElement('p');message.setAttribute('role','status');message.setAttribute('aria-live','polite')
  const close=document.createElement('button');close.type='button';close.textContent='Dismiss'
  notice.append(noticeImage,message,close);document.body.appendChild(notice)
  function pageName() {
    return root.querySelector('.menu [aria-current="page"]')?.dataset.page || 'home'
  }
  function baseState() {
    const page=pageName()
    if(page==='home') return 'greeting'
    if(page==='pomodoro') {
      const mode=root.querySelector('#timerMode')?.textContent?.toLowerCase() || ''
      if(mode.includes('break')) return 'sleeping'
      return root.querySelector('#toggleTimer')?.textContent?.trim()==='Pause' ? 'studious' : 'break'
    }
    return page==='flashcards'||page==='planner' ? 'studious' : 'greeting'
  }
  function setFigure(figure,state) {
    if(figure.dataset.petState===state) return
    const image=document.createElement('img');image.className='pet-art';image.src=PET_ART[state];image.alt=COPY[state][0]
    const caption=document.createElement('figcaption');caption.textContent=COPY[state][1]
    figure.dataset.petState=state;figure.replaceChildren(image,caption)
  }
  function dismiss() {
    clearTimeout(noticeTimer);noticeState=null;notice.hidden=true;message.textContent='';schedule()
  }
  close.addEventListener('click',dismiss)
  function showNotice(text,state='celebrating') {
    clearTimeout(noticeTimer);noticeState=state
    noticeImage.src=PET_ART[state];message.textContent=text;notice.hidden=false
    noticeTimer=setTimeout(dismiss,state==='celebrating'?5500:3500);schedule()
  }
  function render() {
    scheduled=false
    const main=root.querySelector('#mainContent');if(!main)return
    const page=pageName()
    if((page==='flashcards'||page==='planner')&&!main.querySelector('figure.pet')) {
      const aside=document.createElement('aside');aside.className='pet-companion';aside.setAttribute('aria-label','Study companion')
      const figure=document.createElement('figure');figure.className='pet';aside.appendChild(figure);main.appendChild(aside)
    }
    const status=root.querySelector('#timerStatus')?.textContent || ''
    const time=root.querySelector('#timerValue')?.textContent || ''
    if(page==='pomodoro'&&time==='00:00'&&status.includes('Study session complete')) {
      if(previousCompletion!=='study-complete'){previousCompletion='study-complete';showNotice('Study session complete. Nice work!')}
    } else if(page==='pomodoro'&&time!=='00:00') previousCompletion=''
    const state=noticeState || baseState()
    main.querySelectorAll('figure.pet').forEach(f=>setFigure(f,state))
  }
  function schedule() { if(!scheduled){scheduled=true;requestAnimationFrame(render)} }
  // Capture the user action without changing the app's existing handlers.
  root.addEventListener('change',event=>{
    const input=event.target
    if(input.matches('.task-label input[type="checkbox"]')) {
      const done=input.checked
      setTimeout(()=>showNotice(done?'Task complete. Nice work!':'Task marked as not done.',done?'celebrating':'studious'))
    }
  },true)
  root.addEventListener('click',event=>{
    const button=event.target.closest('button[aria-label^="Delete task:"]')
    if(!button)return
    const row=button.closest('.task-row')
    setTimeout(()=>{if(row&&!row.isConnected&&pageName()==='planner')showNotice('Task removed.','greeting')})
  },true)
  new MutationObserver(schedule).observe(root,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-current']})
  schedule()
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initPetUpgrade,{once:true})
else initPetUpgrade()
